import AgentsCore
import Foundation
import Markdown

/// Pure UTF-8 transformations. Filesystem access and lifecycle authorization belong to the caller.
public enum Instructions {
  /// The first line of every generated target. A file that starts with it is owned by the tool.
  public static let notice =
    "<!-- Generated by agents from instruction files. Edit those files and run `agents update`. -->"

  /// Validates an instructions file: front matter, a body that starts with an ATX heading whose
  /// level every other heading exceeds, and an end outside code and HTML blocks.
  public static func validateSource(_ bytes: Data, id: String) throws -> InstructionSection {
    guard String(data: bytes, encoding: .utf8) != nil else { throw InstructionError.invalidUTF8 }
    func invalid(_ reason: String) -> InstructionError { .invalidSource(id: id, reason: reason) }
    var text = String(decoding: bytes, as: UTF8.self)
    if text.first == "\u{FEFF}" { text.removeFirst() }
    let lines = MarkdownLine.parse(text).map(\.text)
    guard lines.first == "---", let close = lines.dropFirst().firstIndex(of: "---") else {
      throw invalid("the file must start with front matter between '---' lines.")
    }
    let front: InstructionFrontMatter
    do {
      front = try InstructionFrontMatter.parse(Array(lines[1..<close]))
    } catch let failure as InstructionFrontMatter.Failure {
      throw invalid(failure.reason)
    }
    for pattern in front.paths {
      if let reason = patternProblem(pattern) { throw invalid("path '\(pattern)' \(reason)") }
    }
    var body = Array(lines[(close + 1)...])
    while body.first.map(isBlank) == true { body.removeFirst() }
    while body.last.map(isBlank) == true { body.removeLast() }
    let document = MarkdownDocument(body.joined(separator: "\n"))
    guard let first = document.topLevelHeadings.first, first.isATX, first.lines.lowerBound == 0
    else { throw invalid("the body must start with an ATX heading.") }
    guard document.headings.allSatisfy(\.isATX) else {
      throw invalid("Setext headings are not allowed; use ATX headings.")
    }
    guard
      document.headings.allSatisfy({ $0.lines.lowerBound == 0 || $0.level > first.level })
    else { throw invalid("every heading after the first must be deeper than the first.") }
    guard !document.endsInCode else { throw invalid("the body ends inside a code block.") }
    guard !document.endsInHTML else { throw invalid("the body ends inside an HTML block.") }
    if !front.paths.isEmpty {
      var rest = Array(body.dropFirst())
      while rest.first.map(isBlank) == true { rest.removeFirst() }
      let scope =
        "Applies when working on files matching "
        + front.paths.map { "`\($0)`" }.joined(separator: ", ") + "."
      body = [body[0], "", scope] + (rest.isEmpty ? [] : [""] + rest)
    }
    return InstructionSection(
      id: id, level: first.level, heading: first.key, description: front.description,
      paths: front.paths, hash: hash(bytes), content: body.joined(separator: "\n"))
  }

  /// The longest directory shared by the literal prefixes of `paths`, relative to the project
  /// root; empty when there are no patterns or a pattern starts with a wildcard. A pattern without
  /// wildcards names a file, so its prefix is that file's directory.
  public static func directory(for paths: [String]) -> String {
    let prefixes = paths.map { pattern -> [Substring] in
      let segments = pattern.split(separator: "/")
      let literal = segments.prefix { !$0.contains("*") && !$0.contains("?") }
      return literal.count == segments.count ? Array(literal.dropLast()) : Array(literal)
    }
    guard var common = prefixes.first else { return "" }
    for prefix in prefixes.dropFirst() {
      common = zip(common, prefix).prefix { $0 == $1 }.map(\.0)
    }
    return common.joined(separator: "/")
  }

  /// Renders a generated target: the notice, then the sections in order, one blank line apart.
  /// The result is parsed again; every section's first heading must stay a document heading.
  public static func render(_ sections: [InstructionSection]) throws -> String {
    guard !sections.isEmpty else { throw InstructionError.invalidAssembly }
    try validateSelection(sections)
    var lines = [notice, ""]
    var expected: [(line: Int, level: Int)] = []
    for (index, section) in sections.enumerated() {
      if index > 0 { lines.append("") }
      expected.append((lines.count, section.level))
      lines += section.content.split(separator: "\n", omittingEmptySubsequences: false).map(
        String.init)
    }
    let text = lines.joined(separator: "\n") + "\n"
    let document = MarkdownDocument(text)
    for heading in expected {
      guard
        document.topLevelHeadings.contains(where: {
          $0.lines.lowerBound == heading.line && $0.level == heading.level
        })
      else { throw InstructionError.invalidAssembly }
    }
    return text
  }

  /// Whether the file starts with the notice, after an optional byte order mark.
  public static func isGenerated(_ bytes: Data) -> Bool {
    var text = String(decoding: bytes, as: UTF8.self)
    if text.first == "\u{FEFF}" { text.removeFirst() }
    return MarkdownLine.parse(text).first?.text == notice
  }

  /// Sections render as in targets, without the notice. Custom text follows after one blank line.
  public static func renderChatGPT(
    sections: [InstructionSection], customContent: Data? = nil
  ) throws -> Data {
    guard !sections.isEmpty else { throw InstructionError.emptyPrompt }
    try validateSelection(sections)
    var output = Data((sections.map(\.content).joined(separator: "\n\n") + "\n").utf8)
    if let customContent, !customContent.isEmpty {
      guard String(data: customContent, encoding: .utf8) != nil else {
        throw InstructionError.invalidUTF8
      }
      output.append(10)
      output.append(customContent)
    }
    return output
  }

  /// Links, images and reference definitions with local destinations, and raw HTML links, outside
  /// code. URLs with a scheme other than `file:` and bare fragments are omitted.
  public static func localLinks(in text: String) -> [InstructionLink] {
    var result: [InstructionLink] = []
    func add(_ kind: InstructionLink.Kind, _ destination: String) {
      if let path = localPath(destination) {
        result.append(InstructionLink(kind: kind, destination: destination, path: path))
      }
    }
    let document = Document(parsing: text, options: [.disableSmartOpts])
    var code = IndexSet()
    var pending: [Markup] = [document]
    while let node = pending.popLast() {
      if let link = node as? Link {
        add(.link, link.destination ?? "")
      } else if let image = node as? Image {
        add(.image, image.source ?? "")
      }
      let html = (node as? InlineHTML)?.rawHTML ?? (node as? HTMLBlock)?.rawHTML
      if let html, html.range(of: #"(?i)\b(href|src)\s*="#, options: .regularExpression) != nil {
        result.append(InstructionLink(kind: .html, destination: html, path: nil))
      }
      if node is CodeBlock || node is HTMLBlock, let range = node.range {
        code.insert(integersIn: (range.lowerBound.line - 1)..<range.upperBound.line)
      }
      if node is CodeBlock || node is InlineCode || node is HTMLBlock { continue }
      pending.append(contentsOf: node.children.reversed())
    }
    // The parser consumes reference definitions, so read them from the lines outside code.
    let definition = try! NSRegularExpression(
      pattern: #"^ {0,3}\[(?:[^\]\\]|\\.)+\]:[ \t]*(<[^>\n]*>|\S+)"#)
    for (index, line) in MarkdownLine.parse(text).enumerated() where !code.contains(index) {
      let range = NSRange(line.text.startIndex..., in: line.text)
      guard let match = definition.firstMatch(in: line.text, range: range),
        let value = Range(match.range(at: 1), in: line.text)
      else { continue }
      var destination = String(line.text[value])
      if destination.hasPrefix("<") { destination = String(destination.dropFirst().dropLast()) }
      add(.definition, destination)
    }
    return result
  }

  /// The decoded path of a local destination, or nil for a fragment or a non-file URL.
  /// An empty destination is local and yields an empty path.
  static func localPath(_ destination: String) -> String? {
    let value = destination.trimmingCharacters(in: .whitespaces)
    if value.hasPrefix("#") { return nil }
    if let scheme = value.range(of: #"^[A-Za-z][A-Za-z0-9+.-]*:"#, options: .regularExpression) {
      guard value[scheme].lowercased() == "file:" else { return nil }
      return URL(string: value)?.path ?? ""
    }
    let end = value.firstIndex { $0 == "?" || $0 == "#" } ?? value.endIndex
    let path = String(value[..<end])
    return path.removingPercentEncoding ?? path
  }

  /// Source-qualified identities installed in both scopes, in project order, for doctor warnings.
  public static func sectionsInBothScopes(user: [String], project: [String]) -> [String] {
    let installed = Set(user)
    var seen: Set<String> = []
    return project.filter { installed.contains($0) && seen.insert($0).inserted }
  }

  /// Compares the managed block of a Claude file with its locked hash.
  public static func detectDrift(in bytes: Data, lockedBlockHash: String) throws
    -> InstructionDrift
  {
    let document = try MarkdownDocument(bytes: bytes)
    guard let range = try document.managedBlock() else { return .missing }
    let actual = document.normalized(range)
    return hash(Data(actual.utf8)) == lockedBlockHash ? .clean : .drifted
  }

  static func hash(_ bytes: Data) -> String { "sha256:" + FileHash.sha256Hex(data: bytes) }

  static func patternProblem(_ pattern: String) -> String? {
    guard !pattern.isEmpty, !pattern.hasPrefix("/") else { return "must be project-relative." }
    guard !pattern.contains(where: { "\\`[]{}\0".contains($0) }) else {
      return "may use only the wildcards '*', '**' and '?'."
    }
    let segments = pattern.split(separator: "/", omittingEmptySubsequences: false)
    for segment in segments {
      if segment.isEmpty || segment == "." || segment == ".." {
        return "must not have empty, '.' or '..' segments."
      }
      if segment.contains("**"), segment != "**" { return "may use '**' only as a whole segment." }
    }
    return nil
  }

  /// Removes a Claude file's managed block and its adjacent separating blanks, retaining other
  /// bytes except trailing blank lines and the final line ending, which become a single LF.
  static func removeBlock(from bytes: Data) throws -> (bytes: Data, hasCustomContent: Bool) {
    let document = try MarkdownDocument(bytes: bytes)
    guard let block = try document.managedBlock() else {
      return (bytes, !document.lines.isEmpty)
    }
    var lower = block.lowerBound
    var upper = block.upperBound
    if lower > 0, document.lines[lower - 1].isBlank { lower -= 1 }
    if upper < document.lines.count, document.lines[upper].isBlank { upper += 1 }
    var custom = Array(document.lines[..<lower]) + Array(document.lines[upper...])
    while custom.last?.isBlank == true { custom.removeLast() }
    var output = custom.dropLast().map(\.raw).joined()
    if let last = custom.last { output += last.text + "\n" }
    try validateAssembly(output, expected: nil)
    return (document.byteOrderMark + Data(output.utf8), !output.isEmpty)
  }

  static func validateAssembly(_ text: String, expected: String?) throws {
    let document = MarkdownDocument(text)
    do {
      let actual = try document.managedBlock().map { document.normalized($0) }
      guard actual == expected else { throw InstructionError.invalidAssembly }
    } catch {
      throw InstructionError.invalidAssembly
    }
  }

  static func separatedPrefix(_ text: String) -> String {
    guard !text.isEmpty else { return "" }
    return text + (text.utf8.last == 10 ? "\n" : "\n\n")
  }

  private static func isBlank(_ line: String) -> Bool {
    line.allSatisfy { $0 == " " || $0 == "\t" }
  }

  private static func validateSelection(_ sections: [InstructionSection]) throws {
    let byHeading = Dictionary(grouping: sections) { "\($0.level) \($0.heading)" }
    for section in sections {
      if let duplicates = byHeading["\(section.level) \(section.heading)"], duplicates.count > 1 {
        throw InstructionError.duplicateHeading(
          heading: section.heading, sectionIDs: duplicates.map(\.id))
      }
    }
  }

}
